"""[bf16 variant] AlphaChooser: clamp(1 + sigmoid(pre_alpha), 1.01, 2)."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'AlphaChooser_16276',
    'head_count': 33554432,
    'alpha_min': 1.01,
    'alpha_max': 2.0,
}


def create_inputs(dtype=jnp.bfloat16):
    key = jax.random.key(0)
    # Unscaled normal to match torch.randn init, so the min clamp is exercised.
    pre_alpha = jax.random.normal(key, (CONFIG['head_count'],), dtype)
    return (pre_alpha,)


def workload(pre_alpha):
    alpha = 1 + jax.nn.sigmoid(pre_alpha)
    return jnp.clip(alpha, CONFIG['alpha_min'], CONFIG['alpha_max'])

"""BetaMish: x * tanh(log((1 + exp(x)) ** beta)), elementwise."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'BetaMish_3429',
    'batch': 16,
    'channels': 64,
    'height': 256,
    'width': 256,
    'beta': 1.5,
}


def create_inputs(dtype=jnp.float32):
    key = jax.random.key(0)
    shape = (CONFIG['batch'], CONFIG['channels'], CONFIG['height'], CONFIG['width'])
    x = jax.random.uniform(key, shape, dtype)
    return (x,)


def workload(x):
    beta = CONFIG['beta']
    return x * jnp.tanh(jnp.log(jnp.power(1 + jnp.exp(x), beta)))

"""BinaryReg: alpha * mean(1 / clamp(|pred - 0.5|, min=0.01))."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'BinaryReg_3980',
    'batch': 16,
    'channels': 64,
    'height': 256,
    'width': 256,
    'alpha': 0.1,
    'clamp_min': 0.01,
}


def create_inputs(dtype=jnp.float32):
    key = jax.random.key(0)
    shape = (CONFIG['batch'], CONFIG['channels'], CONFIG['height'], CONFIG['width'])
    pred = jax.random.uniform(key, shape, dtype)
    return (pred,)


def workload(pred):
    diff = jnp.maximum(jnp.abs(pred - 0.5), CONFIG['clamp_min'])
    return CONFIG['alpha'] * jnp.mean(1.0 / diff)

"""[bf16 variant] Cartesian: polar (r, phi) in last axis -> stack(r*cos(phi), r*sin(phi))."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'Cartesian_13697',
    'batch': 16,
    'dim1': 512,
    'dim2': 1024,
    'channels': 4,
}


def create_inputs(dtype=jnp.bfloat16):
    key = jax.random.key(0)
    x = jax.random.uniform(
        key,
        (CONFIG['batch'], CONFIG['dim1'], CONFIG['dim2'], CONFIG['channels']),
        dtype=dtype,
    )
    return (x,)


def workload(x):
    r = x[..., 0]
    phi = x[..., 1]
    return jnp.stack((r * jnp.cos(phi), r * jnp.sin(phi)), axis=-1)

"""[bf16 variant] GELU (tanh approximation): 0.5*x*(1+tanh(sqrt(2/pi)*(x+0.044715*x^3)))."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'GELU_2265',
    'shape': (32, 128, 128, 128),
    'cubic_coeff': 0.044715,
}


def create_inputs(dtype=jnp.bfloat16):
    key = jax.random.key(0)
    x = jax.random.uniform(key, CONFIG['shape'], dtype=dtype)
    return (x,)


def workload(x):
    c = jnp.sqrt(2.0 / jnp.pi).astype(x.dtype)
    inner = c * (x + CONFIG['cubic_coeff'] * x ** 3)
    return 0.5 * x * (1.0 + jnp.tanh(inner))

"""GELU (tanh approximation): 0.5*x*(1+tanh(sqrt(2/pi)*(x+0.044715*x^3)))."""
import math

import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'GELU__7911',
    'shape': (16, 128, 128, 128),
    'sqrt_2_over_pi': math.sqrt(2 / math.pi),
    'cubic_coeff': 0.044715,
}


def create_inputs(dtype=jnp.float32):
    key = jax.random.key(0)
    x = jax.random.uniform(key, CONFIG['shape'], dtype)
    return (x,)


def workload(x):
    inner = CONFIG['sqrt_2_over_pi'] * (x + CONFIG['cubic_coeff'] * jnp.power(x, 3))
    return 0.5 * x * (1 + jnp.tanh(inner))

"""NegativeLearningLoss: mask(p < thr) * -log(1 - p + eps), summed and divided by the mask count."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'NegativeLearningLoss_16953',
    'batch': 16,
    'channels': 128,
    'height': 128,
    'width': 128,
    'threshold': 0.05,
    'eps': 1e-6,
}


def create_inputs(dtype=jnp.float32):
    shape = (CONFIG['batch'], CONFIG['channels'], CONFIG['height'], CONFIG['width'])
    predict = jax.random.uniform(jax.random.key(0), shape, dtype)
    return (predict,)


def workload(predict):
    mask = (predict < CONFIG['threshold']).astype(predict.dtype)
    loss_item = -1.0 * mask * jnp.log(1.0 - predict + CONFIG['eps'])
    return jnp.sum(loss_item) / jnp.sum(mask)

"""[bf16 variant] PixelNorm: x / sqrt(mean(x**2 over channels) + eps)."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'PixelNorm_16870',
    'batch': 16,
    'channels': 256,
    'height': 128,
    'width': 128,
    'eps': 1e-8,
}


def create_inputs(dtype=jnp.bfloat16):
    key = jax.random.key(0)
    x = jax.random.uniform(
        key,
        (CONFIG['batch'], CONFIG['channels'], CONFIG['height'], CONFIG['width']),
        dtype,
    )
    return (x,)


def workload(x):
    ms = jnp.mean(x * x, axis=1, keepdims=True)
    return x / jnp.sqrt(ms + CONFIG['eps'])

"""make_style: global avg_pool2d over HxW -> flatten -> L2 normalize over channels."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'make_style_12017',
    'batch': 16,
    'channels': 512,
    'height': 128,
    'width': 128,
}


def create_inputs(dtype=jnp.float32):
    key = jax.random.key(0)
    x0 = jax.random.uniform(
        key,
        (CONFIG['batch'], CONFIG['channels'], CONFIG['height'], CONFIG['width']),
        dtype=dtype,
    )
    return (x0,)


def workload(x0):
    # avg_pool2d with kernel = full spatial extent is a mean over H, W; flatten gives (N, C).
    style = jnp.mean(x0, axis=(2, 3))
    return style / jnp.sqrt(jnp.sum(style ** 2, axis=1, keepdims=True))

